package com.him.landlordtenant.app.enums

/**
 * =============================================================
 * NOTIFICATION TYPE
 * =============================================================
 *
 * Central list of notification events generated by the system.
 *
 * Notifications may be triggered by:
 * - Tenant actions
 * - Landlord actions
 * - Caretaker actions
 * - Broker actions
 * - Professional actions
 * - Payments
 * - Agreements
 * - Maintenance
 * - Property events
 * - Verification
 * - Automated system rules
 *
 * =============================================================
 */

