    /*
     * ---------------------------------------------------------
     * HELPERS
     * ---------------------------------------------------------
     */

    val isUrgent: Boolean
        get() =
            defaultPriority == NotificationPriority.CRITICAL

    val isFinancial: Boolean
        get() =
            category == NotificationCategory.FINANCE

    val isMaintenance: Boolean
        get() =
            category == NotificationCategory.MAINTENANCE ||
                    category == NotificationCategory.EMERGENCY

    val isAgreement: Boolean
        get() =
            category == NotificationCategory.AGREEMENT

    val isMessage: Boolean
        get() =
            category == NotificationCategory.MESSAGING

    val isPropertyRelated: Boolean
        get() =
            category == NotificationCategory.PROPERTY

    val isVerificationRelated: Boolean
        get() =
            category == NotificationCategory.VERIFICATION

    val isSecurityRelated: Boolean
        get() =
            category == NotificationCategory.SECURITY ||
                    category == NotificationCategory.EMERGENCY

    companion object {

        fun fromValue(value: String?): NotificationType? {
            if (value.isNullOrBlank()) return null

            return entries.firstOrNull {
                it.name.equals(value, ignoreCase = true) ||
                        it.displayName.equals(value, ignoreCase = true)
            }
        }

        fun fromValueOrDefault(
            value: String?,
            default: NotificationType = SYSTEM_ANNOUNCEMENT
        ): NotificationType {
            return fromValue(value) ?: default
        }
    }
}
